multi-armed-bandit.pseudocode:
def ucb_select(counts, values, t, c=2):
    import math
    n = len(counts)
    for i in range(n):
        if counts[i] == 0:
            return i  # 미시도 암 우선
    def ucb(i):
        avg = values[i]  # 추정 평균 보상
        bonus = c * math.sqrt(math.log(t) / counts[i])
        return avg + bonus  # 활용 + 탐색 보너스
    return max(range(n), key=ucb)

def update(counts, values, arm, reward):
    counts[arm] += 1
    n = counts[arm]
    # 증분 평균 갱신
    values[arm] += (reward - values[arm]) / n

multi-version-concurrency-control.pseudocode:
def visible(v, snap):  # snap: 스냅샷 정보
    c, d = v.created_by, v.deleted_by
    if c != snap.my_tx:
        if c >= snap.xmax or c in snap.active:
            return False  # 스냅샷 이후·진행 중 생성
        if not committed(c):
            return False  # 철회된 생성
    if d is None:
        return True
    if d == snap.my_tx:
        return False  # 내가 삭제함
    if d >= snap.xmax or d in snap.active:
        return True  # 삭제가 아직 안 보임
    return not committed(d)  # 철회된 삭제면 보임

def read(row, snap):  # 잠금 없이 읽기
    v = row.newest
    while v is not None and not visible(v, snap):
        v = v.prev  # 이전 버전으로 이동
    return v

multipoint-relay.pseudocode:
def select_mpr(n1, n2_of):
    # n1: 1홉 이웃, n2_of[v]: v로 닿는 2홉 이웃(자신 제외)
    two_hop = set().union(*(n2_of[v] for v in n1)) - n1
    mpr, covered = set(), set()
    # 1) 한 이웃으로만 닿는 2홉이 있으면 그 이웃 필수
    for t in two_hop:
        via = [v for v in n1 if t in n2_of[v]]
        if len(via) == 1:
            mpr.add(via[0])
    for v in mpr:
        covered |= n2_of[v]
    # 2) 남은 2홉을 가장 많이 덮는 이웃부터 탐욕 선택
    while two_hop - covered:
        rest = two_hop - covered
        gain = lambda v: len(n2_of[v] & rest)
        best = max(n1 - mpr, key=gain)
        mpr.add(best)
        covered |= n2_of[best]
    return mpr

# n2_of = {A: {X, Y}, B: {Y, W}, C: {W, Z}} → {A, C}

mutant.pseudocode:
def mutation_score(program, operators, tests, is_equiv):
    # 전제: 모든 테스트가 원본 program에서 통과
    killed = total = 0
    for op in operators:
        for mutant in op.apply_once(program):
            if is_equiv(mutant):  # 동등 뮤턴트 제외
                continue
            total += 1
            for t in tests:
                if not t.passes(mutant):  # 실패 = 탐지
                    killed += 1
                    break
    return killed / total if total else 1.0
